remaining = dict(stock)
outcomes = []
for order in orders:
    accepted = all(remaining[sku] >= quantity for sku, quantity in order["items"])
    if accepted:
        for sku, quantity in order["items"]:
            remaining[sku] -= quantity
    outcomes.append({"order_id": order["id"], "accepted": accepted})
return remaining, outcomes

def test_rejection_alone_leaves_every_quantity_unchanged(self):
    self.assert_both_apis(
        {"a": 4, "b": 1, "unused": 9},
        [{"id": "reject", "items": [["a", 3], ["b", 2]]}],
        ({"a": 4, "b": 1, "unused": 9}, [{"order_id": "reject", "accepted": False}]),
    )
